<header class="pp-page-heading pc-heading"><div><p class="pp-eyebrow"><?php esc_html_e('Petish Passport · Pet Club','petish-passport'); ?></p><h1><?php echo esc_html($favourites?__('Your favourite little faces.','petish-passport'):__('Meet the little neighbours.','petish-passport')); ?></h1><p class="pp-intro"><?php echo esc_html($favourites?__('The pets you’ve saved, all in one little place.','petish-passport'):__('Small pets, big personalities. A little community made by their people.','petish-passport')); ?></p></div><a class="pp-button pp-button-secondary" href="<?php echo esc_url(self::url()); ?>"><?php echo self::icon('plus'); ?><?php echo esc_html(is_user_logged_in()?__('My Pets','petish-passport'):__('Join the little community','petish-passport')); ?></a></header>
<?php self::club_notice(); ?>
<nav class="pc-directory-nav" aria-label="<?php esc_attr_e('Pet Club views','petish-passport'); ?>"><a href="<?php echo esc_url(Petish_Passport_Community::directory_url(array_merge($filters,array('view'=>'all')))); ?>" <?php if(!$favourites)echo 'aria-current="page"'; ?>><?php esc_html_e('All pets','petish-passport'); ?></a><a href="<?php echo esc_url(Petish_Passport_Community::directory_url(array_merge($filters,array('view'=>'favourites')))); ?>" <?php if($favourites)echo 'aria-current="page"'; ?>><?php echo self::icon('heart'); ?><?php esc_html_e('My favourites','petish-passport'); ?></a></nav>
<?php if($login_required): ?>
<section class="pc-empty pc-welcome"><span class="pc-empty-icon"><?php echo self::icon('heart'); ?></span><h2><?php esc_html_e('Keep your favourite little faces close.','petish-passport'); ?></h2><p><?php esc_html_e('Sign in to save pets with a heart and find your favourites here. Your saved list is private to your account.','petish-passport'); ?></p><a class="pp-button" href="<?php echo esc_url(wp_login_url(Petish_Passport_Community::directory_url($filters,$pagination['page']))); ?>"><?php esc_html_e('Sign in to see favourites','petish-passport'); ?></a><a class="pc-text-link pc-empty-link" href="<?php echo esc_url(Petish_Passport_Community::directory_url()); ?>"><?php esc_html_e('Browse Pet Club','petish-passport'); ?> <span aria-hidden="true">→</span></a></section>
<?php else: ?>
<form class="pc-directory-filters" method="get" action="<?php echo esc_url(home_url('/')); ?>" role="search" aria-label="<?php esc_attr_e('Find pets in Pet Club','petish-passport'); ?>" data-pc-directory-filters>
<input type="hidden" name="petish_club" value="1"><input type="hidden" name="club_view" value="<?php echo esc_attr($filters['view']); ?>">
<div class="pc-filter-field"><label for="pc-club-species"><?php esc_html_e('Species','petish-passport'); ?></label><select id="pc-club-species" name="club_species" data-pc-filter-species><option value=""><?php esc_html_e('All species','petish-passport'); ?></option><?php foreach(Petish_Passport_Store::species() as $key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($filters['species'],$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div>
<div class="pc-filter-field"><label for="pc-club-variety"><?php esc_html_e('Breed or variety','petish-passport'); ?></label><input id="pc-club-variety" name="club_variety" type="search" value="<?php echo esc_attr($filters['variety']); ?>" maxlength="60" list="pc-club-varieties" autocomplete="off" aria-describedby="pc-club-variety-help" data-pc-filter-variety><span class="pc-filter-hint" id="pc-club-variety-help"><?php esc_html_e('Type any variety, including a custom one.','petish-passport'); ?></span><datalist id="pc-club-varieties" data-pc-filter-suggestions><?php foreach(Petish_Passport_Store::varieties() as $species=>$choices): foreach($choices as $key=>$label): if('other'===$key)continue; ?><option value="<?php echo esc_attr($label); ?>" label="<?php echo esc_attr(self::label('species',$species).' · '.$label); ?>" data-species="<?php echo esc_attr($species); ?>"></option><?php endforeach; endforeach; ?></datalist></div>
<div class="pc-filter-field pc-filter-name"><label for="pc-club-name"><?php esc_html_e('Pet name','petish-passport'); ?></label><input id="pc-club-name" name="club_name" type="search" value="<?php echo esc_attr($filters['name']); ?>" maxlength="80" autocomplete="off"></div>
<div class="pc-filter-actions"><button type="submit" class="pp-button"><?php esc_html_e('Apply filters','petish-passport'); ?></button><a class="pc-text-link" href="<?php echo esc_url($clear_url); ?>"><?php esc_html_e('Clear filters','petish-passport'); ?></a></div>
</form>
<?php if($error): ?><p class="pc-directory-summary pc-directory-error" role="alert"><?php echo esc_html($error); ?></p><?php elseif($indexing): ?><p class="pc-directory-summary" role="status"><?php esc_html_e('We’re updating Pet Club search. Refresh in a moment to see all shared pets.','petish-passport'); ?></p><?php else: ?><p class="pc-directory-summary"><?php echo esc_html(sprintf(_n('%s pet','%s pets',(int)$pagination['total'],'petish-passport'),number_format_i18n($pagination['total']))); ?><?php if($favourites): ?> · <?php esc_html_e('Your saved pets','petish-passport'); ?><?php endif; ?></p><?php endif; ?>
<?php if($profiles): ?><div class="pc-community-grid"><?php foreach($profiles as $profile): ?><article class="pc-community-card"><a class="pc-community-photo" href="<?php echo esc_url($profile['url']); ?>"><?php echo self::public_avatar($profile,true); ?></a><div class="pc-community-info"><p class="pp-eyebrow"><?php echo esc_html(self::label('species',$profile['species'])); ?></p><h2><a href="<?php echo esc_url($profile['url']); ?>"><?php echo esc_html($profile['name']); ?></a></h2><?php if(!empty($profile['variety'])): ?><p class="pc-pet-details"><?php echo esc_html($profile['variety']); ?></p><?php endif; ?><?php if($profile['bio']): ?><p class="pc-community-bio"><?php echo esc_html($profile['bio']); ?></p><?php endif; ?><div class="pc-community-bottom"><div><?php self::heart_control($profile,$return_filters); ?></div><a class="pc-text-link" href="<?php echo esc_url($profile['url']); ?>"><?php esc_html_e('Meet me','petish-passport'); ?> <span aria-hidden="true">→</span></a></div></div></article><?php endforeach; ?></div>
<?php elseif(!$indexing&&!$error): ?>
<section class="pc-empty pc-welcome"><span class="pc-empty-icon"><?php echo self::icon('heart'); ?></span>
<?php if($filtered): ?><h2><?php esc_html_e('No little faces match just yet.','petish-passport'); ?></h2><p><?php esc_html_e('Try a different name, species or variety, or clear your filters to see more pets.','petish-passport'); ?></p><a class="pp-button" href="<?php echo esc_url($clear_url); ?>"><?php esc_html_e('Clear filters','petish-passport'); ?></a>
<?php elseif($favourites): ?><h2><?php esc_html_e('Your favourite little faces, all together.','petish-passport'); ?></h2><p><?php esc_html_e('Save a pet with a heart and find them here whenever you want to visit.','petish-passport'); ?></p><a class="pp-button" href="<?php echo esc_url(Petish_Passport_Community::directory_url()); ?>"><?php esc_html_e('Browse Pet Club','petish-passport'); ?></a>
<?php else: ?><h2><?php esc_html_e('A little community starts here.','petish-passport'); ?></h2><p><?php esc_html_e('There are no shared Passports yet. Create a private Passport for your pet, then choose whether to introduce them to the club.','petish-passport'); ?></p><a class="pp-button" href="<?php echo esc_url(self::url()); ?>"><?php esc_html_e('Visit My Pets','petish-passport'); ?></a><?php endif; ?></section>
<?php endif; ?>
<?php if($pagination['has_prev']||$pagination['has_next']): ?><nav class="pc-directory-pagination" aria-label="<?php esc_attr_e('Pet Club pages','petish-passport'); ?>"><?php if($pagination['has_prev']): ?><a class="pp-button pp-button-secondary" rel="prev" href="<?php echo esc_url(Petish_Passport_Community::directory_url($filters,$pagination['page']-1)); ?>"><?php esc_html_e('Previous','petish-passport'); ?></a><?php endif; ?><span aria-current="page"><?php echo esc_html(sprintf(__('Page %1$s of %2$s','petish-passport'),number_format_i18n($pagination['page']),number_format_i18n($pagination['pages']))); ?></span><?php if($pagination['has_next']): ?><a class="pp-button pp-button-secondary" rel="next" href="<?php echo esc_url(Petish_Passport_Community::directory_url($filters,$pagination['page']+1)); ?>"><?php esc_html_e('Next','petish-passport'); ?></a><?php endif; ?></nav><?php endif; ?>
<?php endif; ?>
<p class="pc-inline-note"><?php echo self::icon('lock'); ?><?php echo esc_html($favourites?__('Your favourites list is private. Pets appear here only while their owners share them publicly.','petish-passport'):__('Every pet here was shared by its owner. Private Passports never appear in the club.','petish-passport')); ?></p>
